import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { mix, uv, color, positionLocal, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const timelines = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];
  const stopA = stops[0]?.hex ?? '#1a1a22';
  const stopB = stops[stops.length - 1]?.hex ?? '#121218';

  // ---------------------------------------------------------------- backdrop stage
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(stopB), color(stopA), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------- local rim light (accent hue, raking)
  const rim = new DirectionalLight(accent, 0.8);
  rim.position.set(-4, 2.2, 1.2);
  root.add(rim);

  // ---------------------------------------------------------------- text content bridging
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find((i) => i.role === 'kicker');
  const brandItems = items.filter((i) => i.role === 'brand-mark');

  // ---------------------------------------------------------------- kicker + accent tick
  const gridTop = 0.745;
  const kickerY = gridTop + 0.3;
  const kickerMats = [];
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(String(kickerItem.text), {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: paper,
      align: 'center',
      letterSpacingPx: (kickerItem.typography?.fontSize ?? 9) * 0.12,
    });
    kicker.position.set(0, kickerY, 0.05);
    root.add(kicker);
    kicker.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        o.material.opacity = 0;
        kickerMats.push(o.material);
      }
    });
  }

  const tickGeo = new PlaneGeometry(0.4, 0.018);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = color(accent);
  tickMat.transparent = true;
  tickMat.opacity = 0;
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(0, kickerY - 0.14, 0.3);
  root.add(tick);
  disposables.push(tickGeo, tickMat);

  // ---------------------------------------------------------------- tile geometry (chamfered slab)
  const TILE_W = 1.0;
  const TILE_H = 0.62;
  const BEVEL = 0.02;
  const shape = new Shape();
  const hw = (TILE_W - BEVEL * 2) / 2;
  const hh = (TILE_H - BEVEL * 2) / 2;
  shape.moveTo(-hw, -hh);
  shape.lineTo(hw, -hh);
  shape.lineTo(hw, hh);
  shape.lineTo(-hw, hh);
  shape.closePath();
  const tileGeo = new ExtrudeGeometry(shape, {
    depth: 0.04,
    bevelEnabled: true,
    bevelThickness: BEVEL,
    bevelSize: BEVEL,
    bevelSegments: 2,
  });
  disposables.push(tileGeo);

  const rampT = clamp(positionLocal.y.add(TILE_H / 2).div(TILE_H), 0, 1);
  const tileColorNode = mix(color(stopA), color(stopB), rampT);

  // ---------------------------------------------------------------- build 3x2 grid
  const PITCH_X = TILE_W + 0.25;
  const PITCH_Y = TILE_H + 0.25;
  const cols = [-PITCH_X, 0, PITCH_X];
  const rows = [PITCH_Y / 2, -PITCH_Y / 2];

  const tiles = [];
  let idx = 0;
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 3; c++) {
      const item = brandItems[idx];
      if (!item) break;

      const tileGroup = new Group();
      const baseY = rows[r];
      tileGroup.position.set(cols[c], baseY, 0);

      const mat = new MeshPhysicalNodeMaterial();
      mat.colorNode = tileColorNode;
      mat.roughness = 0.55;
      mat.metalness = 0.5;
      mat.clearcoat = 0.2;
      mat.anisotropy = 0.6;
      mat.anisotropyRotation = 0;
      mat.transparent = true;
      mat.opacity = 0;
      disposables.push(mat);

      const tileMesh = new Mesh(tileGeo, mat);
      tileMesh.userData.tileIndex = idx;
      tileGroup.add(tileMesh);

      const fontSize = item.typography?.fontSize ?? 13;
      const label = ctx.fontAtlas.createText(String(item.text), {
        fontSize,
        color: paper,
        align: 'center',
        letterSpacingPx: fontSize * 0.08,
      });
      // heuristic fit: shrink long wordmarks to stay inside tile with padding
      const approxWidth = String(item.text).length * fontSize * 0.0068;
      const fit = Math.min(1, 0.84 / Math.max(approxWidth, 0.001));
      label.scale.setScalar(fit);
      label.position.set(0, 0, 0.075);
      const textMats = [];
      label.traverse((o) => {
        o.userData.tileIndex = idx;
        if (o.material) {
          o.material.transparent = true;
          o.material.opacity = 0;
          textMats.push(o.material);
        }
      });
      tileGroup.add(label);

      tileGroup.userData.tileIndex = idx;
      root.add(tileGroup);

      tiles.push({ group: tileGroup, baseY, mat, textMats, hoverTl: null });
      idx++;
    }
  }

  // ---------------------------------------------------------------- mount: stagger-cards, fade-up, top row L->R
  const mountTl = gsap.timeline();
  timelines.push(mountTl);

  kickerMats.forEach((m) => {
    mountTl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });
  mountTl.to(tickMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0.1);

  tiles.forEach((t, i) => {
    const at = 0.12 + i * 0.08;
    mountTl.fromTo(
      t.group.position,
      { y: t.baseY + 0.2 },
      { y: t.baseY, duration: 0.5, ease: 'power2.out' },
      at
    );
    mountTl.to(t.mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, at);
    t.textMats.forEach((m) => {
      mountTl.to(m, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, at);
    });
  });

  // ---------------------------------------------------------------- hover behavior
  function resolveTile(obj) {
    let o = obj;
    while (o) {
      if (o.userData && o.userData.tileIndex !== undefined) return tiles[o.userData.tileIndex];
      o = o.parent;
    }
    return null;
  }

  function hoverTile(tile, on) {
    if (!tile) return;
    if (tile.hoverTl) tile.hoverTl.kill();
    const tl = gsap.timeline();
    tl.to(tile.group.position, {
      z: on ? 0.05 : 0,
      duration: 0.16,
      ease: 'power2.out',
    }, 0);
    tile.textMats.forEach((m) => {
      tl.to(m, { opacity: on ? 1.0 : 0.78, duration: 0.16, ease: 'power2.out' }, 0);
    });
    tile.hoverTl = tl;
  }

  root.userData.handlers = {
    hover: (obj) => hoverTile(resolveTile(obj), true),
    unhover: (obj) => hoverTile(resolveTile(obj), false),
  };

  // ---------------------------------------------------------------- cleanup
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    tiles.forEach((t) => {
      if (t.hoverTl) t.hoverTl.kill();
      t.textMats.forEach((m) => m.dispose && m.dispose());
    });
    kickerMats.forEach((m) => m.dispose && m.dispose());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.remove(rim);
    rim.dispose && rim.dispose();
  };

  return root;
}
